1	// SPDX-License-Identifier: MIT
2	pragma solidity 0.8.24;
3	
4	/// @title WithdrawalQueue
5	/// @notice Records exit requests and enforces the cooldown before assets move.
6	/// @dev This contract is pure bookkeeping — it never holds or moves tokens.
7	///      The vault is the only account permitted to write to it.
8	///
9	///      Invariants:
10	///        - A request is settled at most once (`settled` is monotonic).
11	///        - A request settles only at or after `unlockAt`.
12	///        - Only the recorded `account` can settle its own request.
13	///        - The fee quoted when a request is created is the fee it settles at.
14	contract WithdrawalQueue {
15	    struct Request {
16	        address account;
17	        uint256 assets;
18	        uint64 unlockAt;
19	        bool settled;
20	        /// @dev Fee rate captured when the request was created, so a later fee
21	        ///      change cannot be applied retroactively to a pending exit.
22	        uint256 feeBps;
23	    }
24	
25	    /// @notice The vault permitted to enqueue and settle.
26	    address public immutable vault;
27	
28	    /// @notice Delay between requesting an exit and being able to complete it.
29	    uint64 public immutable cooldown;
30	
31	    /// @notice All requests ever created, indexed by id.
32	    Request[] private _requests;
33	
34	    error NotVault();
35	    error UnknownRequest(uint256 id);
36	    error NotRequestOwner(uint256 id);
37	    error AlreadySettled(uint256 id);
38	    error StillLocked(uint256 id, uint64 unlockAt);
39	
40	    event Enqueued(
41	        uint256 indexed id, address indexed account, uint256 assets, uint64 unlockAt, uint256 feeBps
42	    );
43	    event Settled(uint256 indexed id, address indexed account, uint256 assets);
44	
45	    modifier onlyVault() {
46	        if (msg.sender != vault) revert NotVault();
47	        _;
48	    }
49	
50	    constructor(address vault_, uint64 cooldown_) {
51	        require(vault_ != address(0), "VAULT_ZERO");
52	        vault = vault_;
53	        cooldown = cooldown_;
54	    }
55	
56	    /// @notice Number of requests created so far.
57	    function requestCount() external view returns (uint256) {
58	        return _requests.length;
59	    }
60	
61	    /// @notice Read a request by id.
62	    function requestAt(uint256 id) external view returns (Request memory) {
63	        if (id >= _requests.length) revert UnknownRequest(id);
64	        return _requests[id];
65	    }
66	
67	    /// @notice Record a new exit request for `account`.
68	    /// @param feeBps The exit fee in force now, held for this request.
69	    /// @return id The identifier the account will settle with.
70	    function enqueue(address account, uint256 assets, uint256 feeBps)
71	        external
72	        onlyVault
73	        returns (uint256 id)
74	    {
75	        uint64 unlockAt = uint64(block.timestamp) + cooldown;
76	        _requests.push(
77	            Request({
78	                account: account,
79	                assets: assets,
80	                unlockAt: unlockAt,
81	                settled: false,
82	                feeBps: feeBps
83	            })
84	        );
85	        id = _requests.length - 1;
86	        emit Enqueued(id, account, assets, unlockAt, feeBps);
87	    }
88	
89	    /// @notice Mark request `id` settled on behalf of `caller`.
90	    /// @dev Reverts unless `caller` owns the request, the cooldown has elapsed,
91	    ///      and the request has not been settled before. Returns the amount the
92	    ///      vault owes and the fee rate agreed at request time, so the vault
93	    ///      performs the transfer, not this contract.
94	    function settle(uint256 id, address caller)
95	        external
96	        onlyVault
97	        returns (uint256 assets, uint256 feeBps)
98	    {
99	        if (id >= _requests.length) revert UnknownRequest(id);
100	        Request storage request = _requests[id];
101	
